def get_problem_by_slug(slug: str) -> dict | None:
    """Return problem metadata for a given titleSlug, or None if not found."""
    return DSA_PROBLEMS.get(slug)


def slug_exists(slug: str) -> bool:
    """O(1) check whether a slug is in the master list."""
    return slug in DSA_PROBLEMS


def find_similar_slugs(slug: str, top_n: int = 5) -> list[str]:
    """
    Return up to top_n slugs sharing the most word-tokens with the given slug.
    Used to surface helpful suggestions when a slug is not found.
    """
    parts = set(slug.replace("-", " ").split())
    scores = []
    for s in DSA_PROBLEMS:
        s_parts = set(s.replace("-", " ").split())
        overlap = len(parts & s_parts) / max(len(parts | s_parts), 1)
        if overlap > 0:
            scores.append((overlap, s))
    scores.sort(reverse=True)
    return [s for _, s in scores[:top_n]]